import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ActivatedRoute, RouterModule } from '@angular/router';
import { ApiService } from '../../services/api.service';
import { BlogResponse } from '../../models/models';

@Component({
  selector: 'app-blog-detail',
  standalone: true,
  imports: [CommonModule, RouterModule],
  templateUrl: './blog-detail.component.html',
  styleUrl: './blog-detail.component.css'
})
export class BlogDetailComponent implements OnInit {
  blog: BlogResponse | null = null;
  loading = true;
  error: string | null = null;

  constructor(
    private apiService: ApiService,
    private route: ActivatedRoute
  ) { }

  ngOnInit(): void {
    this.route.params.subscribe(params => {
      const id = params['id'];
      this.loadBlog(id);
    });
  }

  loadBlog(id: number): void {
    this.apiService.getBlogById(id).subscribe({
      next: (data) => {
        this.blog = data;
        this.loading = false;
      },
      error: (err) => {
        console.error('Error loading blog:', err);
        this.error = 'Failed to load blog post';
        this.loading = false;
      }
    });
  }
}
<div class="blog-detail-container">
  <a routerLink="/blogs" class="back-link">← Back to Blogs</a>

  <div *ngIf="loading" class="loading">Loading blog...</div>
  <div *ngIf="error" class="error">{{ error }}</div>

  <article *ngIf="blog && !loading" class="blog-detail">
    <header class="blog-header">
      <h1>{{ blog.title }}</h1>
      <div class="blog-meta">
        <span class="author">By {{ blog.author }}</span>
        <span class="date">{{ blog.date }}</span>
      </div>
    </header>

    <div class="blog-tags">
      <span *ngFor="let tag of blog.tags" class="tag">{{ tag }}</span>
    </div>

    <div class="blog-body">
      {{ blog.content }}
    </div>
  </article>
</div>
